INSERT INTO public.item (id, name, category, pocket, gen, cost, fling_power, fling_effect, effect, short_effect, sprite, showdown_id, holdable, legal_formats) VALUES
  (1, 'master-ball', 'standard-balls', 'pokeballs', 1, 0, NULL, NULL, 'Used in battle : Catches a wild Pokémon without fail. If used in a trainer battle, nothing happens and the ball is lost.', 'Catches a wild Pokémon every time.', 'items/master-ball.png', 'masterball', false, ARRAY['2','3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (2, 'ultra-ball', 'standard-balls', 'pokeballs', 1, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 2×. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Success rate is 2×.', 'items/ultra-ball.png', 'ultraball', false, ARRAY['2','3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (3, 'great-ball', 'standard-balls', 'pokeballs', 1, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1.5×. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Success rate is 1.5×.', 'items/great-ball.png', 'greatball', false, ARRAY['2','3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (4, 'poke-ball', 'standard-balls', 'pokeballs', 1, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon.', 'items/poke-ball.png', 'pokeball', false, ARRAY['2','3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (5, 'safari-ball', 'standard-balls', 'pokeballs', 1, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1.5×. This item can only be used in the Great Marsh or Safari Zone.', 'Tries to catch a wild Pokémon in the Great Marsh or Safari Zone. Success rate is 1.5×.', 'items/safari-ball.png', 'safariball', false, ARRAY['8','9','nationaldex','legendsza']::text[]),
  (6, 'net-ball', 'special-balls', 'pokeballs', 3, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon. If the wild Pokémon is Water- or Bug-type, this ball has a catch rate of 3×. Otherwise, it has a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Success rate is 3× for water and bug Pokémon.', 'items/net-ball.png', 'netball', false, ARRAY['3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (7, 'dive-ball', 'special-balls', 'pokeballs', 3, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon. If the wild Pokémon was encountered by surfing or fishing, this ball has a catch rate of 3.5×. Otherwise, it has a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Success rate is 3.5× when underwater, fishing, or surfing.', 'items/dive-ball.png', 'diveball', false, ARRAY['3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (8, 'nest-ball', 'special-balls', 'pokeballs', 3, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon. Has a catch rate of given by `(40 - level) / 10`, where `level` is the wild Pokémon’s level, to a maximum of 3.9× for level 1 Pokémon. If the wild Pokémon’s level is higher than 30, this ball has a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Success rate is 3.9× for level 1 Pokémon, and drops steadily to 1× at level 30.', 'items/nest-ball.png', 'nestball', false, ARRAY['3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (9, 'repeat-ball', 'special-balls', 'pokeballs', 3, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon. If the wild Pokémon’s species is marked as caught in the trainer’s Pokédex, this ball has a catch rate of 3×. Otherwise, it has a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Success rate is 3× for previously-caught Pokémon.', 'items/repeat-ball.png', 'repeatball', false, ARRAY['3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (10, 'timer-ball', 'special-balls', 'pokeballs', 3, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon. Has a catch rate of 1.1× on the first turn of the battle and increases by 0.1× every turn, to a maximum of 4× on turn 30. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Success rate increases by 0.1× (Gen V: 0.3×) every turn, to a max of 4×.', 'items/timer-ball.png', 'timerball', false, ARRAY['3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (11, 'luxury-ball', 'special-balls', 'pokeballs', 3, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1×. Whenever the caught Pokémon’s happiness increases, it increases by one extra point. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Caught Pokémon start with 200 happiness.', 'items/luxury-ball.png', 'luxuryball', false, ARRAY['3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (12, 'premier-ball', 'special-balls', 'pokeballs', 3, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon.', 'items/premier-ball.png', 'premierball', false, ARRAY['3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (13, 'dusk-ball', 'special-balls', 'pokeballs', 4, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon. If it’s currently nighttime or the wild Pokémon was encountered while walking in a cave, this ball has a catch rate of 3.5×. Otherwise, it has a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Success rate is 3.5× at night and in caves.', 'items/dusk-ball.png', 'duskball', false, ARRAY['4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (14, 'heal-ball', 'special-balls', 'pokeballs', 4, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1×. The caught Pokémon’s HP is immediately restored, PP for all its moves is restored, and any status ailment is cured. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Caught Pokémon are immediately healed.', 'items/heal-ball.png', 'healball', false, ARRAY['4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (15, 'quick-ball', 'special-balls', 'pokeballs', 4, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 4× on the first turn of a battle, but 1× any other time. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon. Success rate is 4× (Gen V: 5×), but only on the first turn.', 'items/quick-ball.png', 'quickball', false, ARRAY['4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (16, 'cherish-ball', 'special-balls', 'pokeballs', 4, 0, NULL, NULL, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', 'Tries to catch a wild Pokémon.', 'items/cherish-ball.png', NULL, false, '{}'),
