  (23, 'full-restore', 'healing', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Restores HP to full and cures any status ailment and confusion.', 'Restores HP to full and cures any status ailment and confusion.', 'items/full-restore.png', NULL, false, '{}'),
  (24, 'max-potion', 'healing', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Restores HP to full.', 'Restores HP to full.', 'items/max-potion.png', NULL, false, '{}'),
