  (27, 'full-heal', 'status-cures', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Cures any status ailment and confusion.', 'Cures any status ailment and confusion.', 'items/full-heal.png', NULL, false, '{}'),
  (28, 'revive', 'revival', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Revives the Pokémon and restores half its HP.', 'Revives with half HP.', 'items/revive.png', NULL, false, '{}'),
  (29, 'max-revive', 'revival', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Revives the Pokémon and restores its HP to full.', 'Revives with full HP.', 'items/max-revive.png', NULL, false, '{}'),
