  (35, 'energy-root', 'healing', 'medicine', 2, 0, 30, NULL, 'Used on a party Pokémon : Restores 200 HP. Decreases happiness by 10/10/15.', 'Restores 200 HP, but lowers happiness.', 'items/energy-root.png', NULL, false, '{}'),
  (36, 'heal-powder', 'status-cures', 'medicine', 2, 0, 30, NULL, 'Used on a party Pokémon : Cures any status ailment. Decreases happiness by 5/5/10.', 'Cures any status ailment, but lowers happiness.', 'items/heal-powder.png', NULL, false, '{}'),
  (37, 'revival-herb', 'revival', 'medicine', 2, 0, 30, NULL, 'Used on a party Pokémon : Revives a fainted Pokémon and restores its HP to full. Decreases happiness by 10/10/15.', 'Revives with full HP, but lowers happiness.', 'items/revival-herb.png', NULL, false, '{}'),
  (38, 'ether', 'pp-recovery', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Restores 10 PP for a selected move.', 'Restores 10 PP for one move.', 'items/ether.png', NULL, false, '{}'),
