  (43, 'berry-juice', 'healing', 'medicine', 2, 0, 30, NULL, 'Used on a party Pokémon : Restores 20 HP.', 'Restores 20 HP.', 'items/berry-juice.png', 'berryjuice', true, ARRAY['2','4','5','6','7','8','nationaldex']::text[]),
  (44, 'sacred-ash', 'revival', 'medicine', 2, 0, 30, NULL, 'Used : Revives all fainted Pokémon in the party and restores their HP to full.', 'Revives all fainted Pokémon with full HP.', 'items/sacred-ash.png', NULL, false, '{}'),
  (45, 'hp-up', 'vitamins', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Increases HP effort by 10, but won’t increase it beyond 100. Increases happiness by 5/3/2.', 'Raises HP effort and happiness.', 'items/hp-up.png', NULL, false, '{}'),
  (46, 'protein', 'vitamins', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Increases Attack effort by 10, but won’t increase it beyond 100. Increases happiness by 5/3/2.', 'Raises Attack effort and happiness.', 'items/protein.png', NULL, false, '{}'),
  (47, 'iron', 'vitamins', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Increases Defense effort by 10, but won’t increase it beyond 100. Increases happiness by 5/3/2.', 'Raises Defense effort and happiness.', 'items/iron.png', NULL, false, '{}'),
  (48, 'carbos', 'vitamins', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Increases Speed effort by 10, but won’t increase it beyond 100. Increases happiness by 5/3/2.', 'Raises Speed effort and happiness.', 'items/carbos.png', NULL, false, '{}'),
  (49, 'calcium', 'vitamins', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Increases Special Attack effort by 10, but won’t increase it beyond 100. Increases happiness by 5/3/2.', 'Raises Special Attack effort and happiness.', 'items/calcium.png', NULL, false, '{}'),
  (50, 'rare-candy', 'vitamins', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Increases level by 1. Increases happiness by 5/3/2.', 'Causes a level-up and raises happiness.', 'items/rare-candy.png', NULL, false, '{}'),
  (51, 'pp-up', 'vitamins', 'medicine', 1, 0, 30, NULL, 'Used on a party Pokémon : Increases a selected move’s max PP by 20% its original max PP, to a maximum of 1.6×. Increases happiness by 5/3/2.', 'Raises a move’s max PP by 20%.', 'items/pp-up.png', NULL, false, '{}'),
  (52, 'zinc', 'vitamins', 'medicine', 3, 0, 30, NULL, 'Used on a party Pokémon : Increases Special Defense effort by 10, but won’t increase it beyond 100. Increases happiness by 5/3/2.', 'Raises Special Defense and happiness.', 'items/zinc.png', NULL, false, '{}'),
  (53, 'pp-max', 'vitamins', 'medicine', 3, 0, 30, NULL, 'Used on a party Pokémon : Increases a selected move’s max PP to 1.6× its original max PP. Increases happiness by 5/3/2.', 'Raises a move’s max PP by 60%.', 'items/pp-max.png', NULL, false, '{}'),
  (54, 'old-gateau', 'status-cures', 'medicine', 4, 0, 30, NULL, 'Used on a party Pokémon : Cures any status ailment and confusion.', 'Cures any status ailment and confusion.', 'items/old-gateau.png', NULL, false, '{}'),
  (55, 'guard-spec', 'stat-boosts', 'battle', 1, 0, 30, NULL, 'Used on a party Pokémon in battle : Protects the target’s stats from being lowered for the next five turns. Increases happiness by 1/1/0.', 'Prevents stat changes in battle for five turns in battle. Raises happiness.', 'items/guard-spec.png', NULL, false, '{}'),
  (56, 'dire-hit', 'stat-boosts', 'battle', 1, 0, 30, NULL, 'Used on a party Pokémon in battle : Increases the target’s critical hit chance by one stage until it leaves the field. Increases happiness by 1/1/0.', 'Increases the chance of a critical hit in battle. Raises happiness.', 'items/dire-hit.png', NULL, false, '{}'),
  (57, 'x-attack', 'stat-boosts', 'battle', 1, 0, 30, NULL, 'Used on a party Pokémon in battle : Raises the target’s Attack by one stage. Increases happiness by 1/1/0.', 'Raises Attack by one stage in battle. Raises happiness.', 'items/x-attack.png', NULL, false, '{}'),
  (58, 'x-defense', 'stat-boosts', 'battle', 1, 0, 30, NULL, 'Used on a party Pokémon in battle : Raises the target’s Defense by one stage. Increases happiness by 1/1/0.', 'Raises Defense by one stage in battle. Raises happiness.', 'items/x-defense.png', NULL, false, '{}'),
  (59, 'x-speed', 'stat-boosts', 'battle', 1, 0, 30, NULL, 'Used on a party Pokémon in battle : Raises the target’s Speed by one stage. Increases happiness by 1/1/0.', 'Raises Speed by one stage in battle. Raises happiness.', 'items/x-speed.png', NULL, false, '{}'),
  (60, 'x-accuracy', 'stat-boosts', 'battle', 1, 0, 30, NULL, 'Used on a party Pokémon in battle : Raises the target’s accuracy by one stage. Increases happiness by 1/1/0.', 'Raises accuracy by one stage in battle. Raises happiness.', 'items/x-accuracy.png', NULL, false, '{}'),
  (61, 'x-sp-atk', 'stat-boosts', 'battle', 1, 0, 30, NULL, 'Used on a party Pokémon in battle : Raises the target’s Special Attack by one stage. Increases happiness by 1/1/0.', 'Raises Special Attack by one stage in battle. Raises happiness.', 'items/x-sp-atk.png', NULL, false, '{}'),
  (62, 'x-sp-def', 'stat-boosts', 'battle', 4, 0, 30, NULL, 'Used on a party Pokémon in battle : Raises the target’s Special Defense by one stage. Increases happiness by 1/1/0.', 'Raises Special Defense by one stage in battle. Raises happiness.', 'items/x-sp-def.png', NULL, false, '{}'),
  (63, 'poke-doll', 'spelunking', 'misc', 1, 0, 30, NULL, 'Used in battle : Ends a wild battle. Cannot be used in trainer battles.', 'Ends a wild battle.', 'items/poke-doll.png', NULL, false, '{}'),
  (64, 'fluffy-tail', 'spelunking', 'misc', 3, 0, 30, NULL, 'Used in battle : Ends a wild battle. Cannot be used in trainer battles.', 'Ends a wild battle.', 'items/fluffy-tail.png', NULL, false, '{}'),
  (65, 'blue-flute', 'flutes', 'battle', 3, 0, 30, NULL, 'Used on a party Pokémon : Cures sleep.', 'Cures sleep.', 'items/blue-flute.png', NULL, false, '{}'),
  (66, 'yellow-flute', 'flutes', 'battle', 3, 0, 30, NULL, 'Used on a party Pokémon in battle : Cures confusion.', 'Cures confusion.', 'items/yellow-flute.png', NULL, false, '{}'),
  (67, 'red-flute', 'flutes', 'battle', 3, 0, 30, NULL, 'Used on a party Pokémon in battle : Cures attraction.', 'Cures attraction.', 'items/red-flute.png', NULL, false, '{}'),
  (68, 'black-flute', 'spelunking', 'misc', 3, 0, 30, NULL, 'Used outside of battle : Decreases the wild Pokémon encounter rate by 50%.', 'Halves the wild Pokémon encounter rate.', 'items/black-flute.png', NULL, false, '{}'),
  (69, 'white-flute', 'spelunking', 'misc', 3, 0, 30, NULL, 'Used outside of battle : Doubles the wild Pokémon encounter rate.', 'Doubles the wild Pokémon encounter rate.', 'items/white-flute.png', NULL, false, '{}'),
  (70, 'shoal-salt', 'collectibles', 'misc', 3, 0, 30, NULL, 'No effect.', 'No effect. Gen III: Trade four and four Shoal Shells for a Shell Bell.', 'items/shoal-salt.png', NULL, false, '{}'),
  (71, 'shoal-shell', 'collectibles', 'misc', 3, 0, 30, NULL, 'No effect.', 'No effect. Gen III: Trade four and four Shoal Salts for a Shell Bell.', 'items/shoal-shell.png', NULL, false, '{}'),
  (72, 'red-shard', 'collectibles', 'misc', 3, 0, 30, NULL, 'No effect. In Diamond and Pearl, trade ten for a Sunny Day TM in the house midway along the southern section of Route 212. In Platinum, trade to move tutors on Route 212, in Snowpoint City, and in the Survival Area. Eight shards total are required per tutelage, but the particular combination of colors varies by move. In HeartGold and SoulSilver, trade one for a Cheri Berry, a Leppa Berry, and a Pecha Berry with the Juggler near the Pokémon Center in Violet City. In HeartGold and SoulSilver, trade one for a Persim Berry, a Pomeg Berry, and a Razz Berry with the Juggler near the Pal Park entrance in Fuchsia City.', 'No effect. Can be traded for items or moves.', 'items/red-shard.png', NULL, false, '{}'),
  (73, 'blue-shard', 'collectibles', 'misc', 3, 0, 30, NULL, 'No effect. In Diamond and Pearl, trade ten for a Rain Dance TM in the house midway along the southern section of Route 212. In Platinum, trade to move tutors on Route 212, in Snowpoint City, and in the Survival Area. Eight shards total are required per tutelage, but the particular combination of colors varies by move. In HeartGold and SoulSilver, trade one for a Chesto Berry, an Oran Berry, and a Wiki Berry with the Juggler near the Pokémon Center in Violet City. In HeartGold and SoulSilver, trade one for a Bluk Berry, a Cornn Berry, and a Kelpsy Berry with the Juggler near the Pal Park entrance in Fuchsia City.', 'No effect. Can be traded for items or moves.', 'items/blue-shard.png', NULL, false, '{}'),
  (74, 'yellow-shard', 'collectibles', 'misc', 3, 0, 30, NULL, 'No effect. In Diamond and Pearl, trade ten for a Sandstorm TM in the house midway along the southern section of Route 212. In Platinum, trade to move tutors on Route 212, in Snowpoint City, and in the Survival Area. Eight shards total are required per tutelage, but the particular combination of colors varies by move. In HeartGold and SoulSilver, trade one for an Aspear Berry, a Iapapa Berry, and a Sitrus Berry with the Juggler near the Pokémon Center in Violet City. In HeartGold and SoulSilver, trade one for a Grepa Berry, a Nomel Berry, and a Pinap Berry with the Juggler near the Pal Park entrance in Fuchsia City.', 'No effect. Can be traded for items or moves.', 'items/yellow-shard.png', NULL, false, '{}'),
  (75, 'green-shard', 'collectibles', 'misc', 3, 0, 30, NULL, 'No effect. In Diamond and Pearl, trade ten for a Hail TM in the house midway along the southern section of Route 212. In Platinum, trade to move tutors on Route 212, in Snowpoint City, and in the Survival Area. Eight shards total are required per tutelage, but the particular combination of colors varies by move. In HeartGold and SoulSilver, trade one for an Aguav Berry, a Lum Berry, and a Rawst Berry with the Juggler near the Pokémon Center in Violet City. In HeartGold and SoulSilver, trade one for a Durin Berry, a Hondew Berry, and a Wepear Berry with the Juggler near the Pal Park entrance in Fuchsia City.', 'No effect. Can be traded for items or moves.', 'items/green-shard.png', NULL, false, '{}'),
  (76, 'super-repel', 'spelunking', 'misc', 1, 0, 30, NULL, 'Used outside of battle : Trainer will skip encounters with wild Pokémon of a lower level than the lead party Pokémon. This effect wears off after the trainer takes 200 steps.', 'For 200 steps, prevents wild encounters of level lower than your party’s lead Pokémon.', 'items/super-repel.png', NULL, false, '{}'),
  (77, 'max-repel', 'spelunking', 'misc', 1, 0, 30, NULL, 'Used outside of battle : Trainer will skip encounters with wild Pokémon of a lower level than the lead party Pokémon. This effect wears off after the trainer takes 250 steps.', 'For 250 steps, prevents wild encounters of level lower than your party’s lead Pokémon.', 'items/max-repel.png', NULL, false, '{}'),
  (78, 'escape-rope', 'spelunking', 'misc', 1, 0, 30, NULL, 'Used outside of battle : Transports the trainer to the last-entered dungeon entrance. Cannot be used outside, in buildings, or in Distortion World, Hall Of Origin, Spear Pillar, or Turnback Cave.', 'Transports user to the outside entrance of a cave.', 'items/escape-rope.png', NULL, false, '{}'),
  (79, 'repel', 'spelunking', 'misc', 1, 0, 30, NULL, 'Used outside of battle : Trainer will skip encounters with wild Pokémon of a lower level than the lead party Pokémon. This effect wears off after the trainer takes 100 steps.', 'For 100 steps, prevents wild encounters of level lower than your party’s lead Pokémon.', 'items/repel.png', NULL, false, '{}'),
  (80, 'sun-stone', 'evolution', 'misc', 2, 0, 30, NULL, 'Used on a party Pokémon : Evolves a Cottonee into Whimsicott, a Gloom into Bellossom, a Petilil into Lilligant, or a Sunkern into Sunflora.', 'Evolves a Cottonee into Whimsicott, a Gloom into Bellossom, a Petilil into Lilligant, or a Sunkern into Sunflora.', 'items/sun-stone.png', 'sunstone', false, ARRAY['2','3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
  (81, 'moon-stone', 'evolution', 'misc', 1, 0, 30, NULL, 'Used on a party Pokémon : Evolves a Clefairy into Clefable, a Jigglypuff into Wigglytuff, a Munna into Musharna, a Nidorina into Nidoqueen, a Nidorino into Nidoking, or a Skitty into Delcatty.', 'Evolves a Clefairy into Clefable, a Jigglypuff into Wigglytuff, a Munna into Musharna, a Nidorina into Nidoqueen, a Nidorino into Nidoking, or a Skitty into Delcatty.', 'items/moon-stone.png', 'moonstone', false, ARRAY['2','3','4','5','6','7','8','9','nationaldex','legendsza']::text[]),
