  (231, 'sea-incense', 'type-enhancement', 'misc', 3, 0, 10, NULL, 'Held: Increases the power of the holder’s Water moves by 20%.', 'Held: Water-Type moves from holder do 20% more damage. Breeding: Marill or Azumarill beget an Azurill Egg.', 'items/sea-incense.png', 'seaincense', true, ARRAY['3','4','5','6','7','8','nationaldex']::text[]),
  (232, 'lax-incense', 'held-items', 'misc', 3, 0, 10, NULL, 'Held: Increases the holder’s Evasion by 5%.', 'Held: Holder’s evasion is increased by 5%. Breeding: Wobbuffet begets a Wynaut Egg.', 'items/lax-incense.png', 'laxincense', true, ARRAY['3','4','5','6','7','8','nationaldex']::text[]),
  (233, 'lucky-punch', 'species-specific', 'misc', 2, 0, 40, NULL, 'Held by Chansey: Raises the holder’s critical hit counter by 2.', 'Raises Chansey’s critical hit ratio by two stages.', 'items/lucky-punch.png', 'luckypunch', true, ARRAY['2','3','4','5','6','7','nationaldex']::text[]),
