  (410, 'journal', 'gameplay', 'key', 4, 0, NULL, NULL, 'Records some of the trainer’s activities for the day.', 'Records prior significant activities the player took.', 'items/journal.png', NULL, false, '{}'),
  (411, 'seal-case', 'gameplay', 'key', 4, 0, NULL, NULL, 'Contains Seals used for decorating Pokéballs.', 'Stores Seals that can be applied to Poké Ball capsules.', 'items/seal-case.png', NULL, false, '{}'),
  (412, 'fashion-case', 'gameplay', 'key', 4, 0, NULL, NULL, 'Contains Pokémon Accessories.', 'Holds Pokémon Accessories for use in Contests.', 'items/fashion-case.png', NULL, false, '{}'),
